import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Upload, X, Globe, ArrowLeft, User, BookOpen, Cpu } from 'lucide-react';

const CandidateRegistration = () => {
  const [skills, setSkills] = useState(['React.js', 'Tailwind CSS', 'Node.js']);
  const navigate = useNavigate();
  const bgImage = "https://i.pinimg.com/1200x/3d/da/0d/3dda0d2769ba87e3b59597ba56f6548e.jpg";

  return (
    <div className="min-h-screen flex flex-col items-center py-12 px-4 relative overflow-hidden font-sans"
      style={{ backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.9), rgba(88, 28, 135, 0.8)), url(${bgImage})`, backgroundSize: 'cover', backgroundAttachment: 'fixed' }}>
      
      {/* Decorative Blur Orbs */}
      <div className="absolute top-0 -left-20 w-96 h-96 bg-purple-500/20 rounded-full blur-[120px]"></div>
      <div className="absolute bottom-0 -right-20 w-96 h-96 bg-blue-500/20 rounded-full blur-[120px]"></div>

      <div className="w-full max-w-4xl flex justify-between items-center mb-8 z-10">
        <div className="flex items-center gap-2 text-white font-black text-2xl tracking-tighter">
          <div className="bg-white/10 p-2 rounded-lg backdrop-blur-md border border-white/20">
            <Globe size={24} className="text-purple-400" />
          </div>
          Talent<span className="text-purple-400">Pool</span>
        </div>
        <button onClick={() => navigate('/register')} className="flex items-center gap-2 text-white/60 hover:text-white font-bold text-xs uppercase tracking-widest transition-all">
          <ArrowLeft size={16} /> Back to Selection
        </button>
      </div>

      <div className="bg-white/10 backdrop-blur-2xl w-full max-w-3xl rounded-[3rem] shadow-2xl border border-white/10 overflow-hidden z-10 animate-in fade-in zoom-in duration-700">
        <div className="p-10 border-b border-white/10 text-center bg-white/5">
          <h1 className="text-3xl font-black text-white tracking-tight">Candidate Registration</h1>
          <p className="text-purple-200/60 text-sm mt-2 font-medium">Verify your professional identity and join the elite pool.</p>
        </div>

        <form className="p-10 space-y-10">
          {/* Account Details */}
          <section className="space-y-6">
            <div className="flex items-center gap-3 text-purple-400 font-black text-xs uppercase tracking-[0.2em]">
              <User size={18} /> Account Credentials
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <input type="text" placeholder="Full Legal Name" className="glass-input" />
              <input type="email" placeholder="Professional Email" className="glass-input" />
              <input type="password" placeholder="Create Password" className="glass-input" />
              <input type="password" placeholder="Confirm Password" className="glass-input" />
            </div>
          </section>

          {/* Education */}
          <section className="space-y-6">
            <div className="flex items-center gap-3 text-purple-400 font-black text-xs uppercase tracking-[0.2em]">
              <BookOpen size={18} /> Education Background
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
              <input type="text" placeholder="University Name" className="glass-input col-span-1" />
              <input type="text" placeholder="Major / Specialization" className="glass-input col-span-1" />
            </div>
          </section>

          {/* Skills Area */}
          <section className="space-y-6">
            <div className="flex items-center gap-3 text-purple-400 font-black text-xs uppercase tracking-[0.2em]">
              <Cpu size={18} /> Skills & Tech Stack
            </div>
            <div className="flex flex-wrap gap-2 p-5 border border-white/10 rounded-[1.5rem] bg-white/5">
              {skills.map(skill => (
                <span key={skill} className="bg-purple-500/20 text-purple-300 px-4 py-1.5 rounded-full text-xs font-black flex items-center gap-2 border border-purple-500/30">
                  {skill} <X size={14} className="cursor-pointer hover:text-white" />
                </span>
              ))}
              <input type="text" placeholder="+ Add Skill" className="bg-transparent outline-none text-white text-xs ml-2 placeholder:text-white/20" />
            </div>
          </section>

          {/* Resume Upload - Glass Style */}
          <section className="space-y-6">
            <div className="border-2 border-dashed border-white/10 rounded-[2rem] p-12 flex flex-col items-center justify-center bg-white/5 hover:bg-white/10 transition-all cursor-pointer group">
              <div className="bg-purple-500/20 p-4 rounded-2xl text-purple-400 mb-4 group-hover:scale-110 transition-transform">
                <Upload size={32} />
              </div>
              <p className="text-white font-bold tracking-tight">Drop your professional CV here</p>
              <p className="text-xs text-white/40 mt-1 uppercase font-black tracking-widest">Maximum File Size: 5MB (PDF Only)</p>
            </div>
          </section>

          <button type="submit" className="w-full bg-gradient-to-r from-purple-600 to-indigo-600 text-white font-black py-5 rounded-2xl shadow-xl hover:brightness-110 transition-all transform active:scale-[0.98] tracking-[0.2em] text-sm">
            COMPLETE VERIFICATION
          </button>
        </form>
      </div>

      <style>{`
        .glass-input {
          width: 100%; padding: 1rem 1.5rem; background: rgba(255, 255, 255, 0.05);
          border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 1.25rem;
          color: white; font-size: 0.875rem; outline: none; transition: all 0.3s;
        }
        .glass-input:focus {
          border-color: #a855f7; background: rgba(255, 255, 255, 0.1);
          box-shadow: 0 0 20px rgba(168, 85, 247, 0.2);
        }
        .glass-input::placeholder { color: rgba(255, 255, 255, 0.3); }
      `}</style>
    </div>
  );
};

export default CandidateRegistration;
